def date(s):return '.'.join(s.split('-')[::-1]) if s else 'не заполнено'
def money(s):return f'{int(float(s)):,}'.replace(',',' ') if s else 'не заполнено'
def table(h,rs):return '\n'+' | '.join(h)+'\n'+' | '.join(['---']*len(h))+'\n'+'\n'.join(' | '.join(str(v) for v in r) for r in rs)+'\n\n'
